INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('b38ad39e-d67b-4b18-a9bf-105ac160e1d5', 'kanji', '花', '花', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Seorang pemimpin dengan sendok sedang menanam bunga agar suatu saat tempat ini penuh dengan bunga-bunga indah.', 'Namun pemimpinnya tidak bisa berhenti menanam bunga. Dia menjadi gila. Mungkinkah itu serbuk sari? Dia mendatangi seseorang bernama Hannah (はな) dan mulai menanam bunga di wajahnya, mungkin membunuhnya dalam prosesnya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
