INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('89a2bbf9-1a3a-4934-951a-364053cf745e', 'kanji', '赤', '赤', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Radikal untuk merah dan kanji untuk merah adalah sama!', 'Pikirkan Fozzie Bear. Dia sering mengatakan "Wakka wakka wakka". Sekarang, pikirkan tentang Fozzie Bear yang jahat, berwarna merah (dan maksud saya benar-benar merah). Dia menghilangkan huruf "w" dan hanya mengatakan "Aka Aka Aka," karena dia benar-benar jahat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
