INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('ad4d64e6-2a2f-4b55-9e15-24af7813ea05', 'kanji', '町', '町', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Saat Anda melihat sawah dan jalan di tempat yang sama, Anda bisa membayangkan sebuah kota yang utuh!', 'Anda pergi mengunjungi kota kecil yang menyenangkan ini. Tapi kemudian, itu dia... Setiap kali kamu berjalan di jalan, wanita jalanan Ny. Chou (ちょう) datang untuk merusak harimu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
