INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('82d9838e-e69f-42bc-89f0-f350cb69cd80', 'kanji', '走', '走', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Lari radikal dan lari kanji sama persis!', 'Anda berlari dan berlari dan berlari dan tiba-tiba Anda merasakan jiwa Anda (そう) meninggalkan tubuh Anda. Masih berlari, Anda berbalik dan melihat jiwa Anda berlari beberapa langkah di belakang Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
