INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('01c8dd0a-0b59-4686-be52-3931ed685a0a', 'kanji', '究', '究', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda menggali sembilan lubang untuk penelitian Anda. Anda harus selalu melakukan penelitian dengan sembilan variabel sehingga Anda dapat membandingkannya sehingga ada angka yang tidak merata.', 'Anda sedang meneliti mentimun (きゅう)!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
