INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('de069c67-164d-4e06-a30f-18621f79d8ee', 'kanji', '図', '図', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Harta karun itu ada di mulut yang ada esnya. Betapa samarnya! Anda ingin menemukan harta karun itu, itu pasti (harta karun itu hebat!). Itu adalah suatu tempat di mana terdapat es, jadi mungkin di kutub? Apa yang Anda lihat adalah diagram yang akan memandu Anda ke sana.', 'Apa yang akan Anda lakukan ketika Anda menemukan harta karun yang ditunjukkan pada diagram ini? Nah, Anda sampai di sana, dan Anda menemukan bahwa harta karun itu sebenarnya adalah seekor mamut berbulu! Apa yang akan kamu lakukan terhadap mamut berbulu ini? Anda mengambilnya dan menaruhnya di kebun binatang Anda (ず).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
