INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('ff696f0b-b6f6-4685-8004-601d91c8f0aa', 'kanji', '弟', '弟', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ada seseorang yang membawa busur dan tongkat, bertanduk, sedang menuruni perosotan. Tipe orang seperti apa yang kamu bayangkan? Menurutku, seseorang adalah anak laki-laki yang belum dewasa. Itu akan menjadi adik laki-lakimu.', 'Adik laki-lakimu sangat suka berdandan sehingga dia sekarang mulai mewarnai rambutnya dengan berbagai warna. Bayangkan pewarna merah cerah, biru, hijau dan ungu di rambutnya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
