INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('beff3cb4-e80b-4463-a409-64041fdd34c3', 'kanji', '事', '事', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda menaruh salib di mulut serigala. Tindakan yang aneh. Mengapa Anda melakukan hal seperti itu? Faktanya adalah Anda tidak terlalu yakin mengapa Anda menaruh salib itu di mulut serigala.', 'Tindakan ini tidak membuat Yesus (じ) terkesan, yang muncul dan dengan lembut melepaskan salib dari mulut serigala.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
