INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('c4b9cee7-cd7f-408c-ab21-0894e799432e', 'kanji', '明', '明', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Matahari DAN bulan sedang terbit? Dengan gabungan kedua kekuatan cahayanya, di luar sangat terang.', 'Kapan keadaan di luar mulai cerah? Menurutku saat cuaca mulai cerah, dan itu adalah bulan Mei (めい). Jika Anda tinggal di Belahan Bumi Selatan, cuaca cerah di bulan Mei karena banyaknya salju, atau karena saat itulah semua lampu jalan menyala.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
