INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('24dd1da3-bdde-449e-aee6-a9315ffb59e6', 'kanji', '知', '知', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Sesaat sebelum mengatakan sesuatu yang penting, kamu mengarahkan anak panah ke mulutmu yang menutup rapat bibirmu, sehingga kamu tidak dapat berbicara. Seseorang tidak ingin Anda membagikan apa yang Anda ketahui kepada orang lain.', 'Untuk mengingat bacaan ち kita menggunakan kata "keju".
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('24dd1da3-bdde-449e-aee6-a9315ffb59e6', 'Tahu', true) ON CONFLICT DO NOTHING;
