INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('30622d15-a410-4970-b21f-2a15eb29d597', 'kanji', '物', '物', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Seekor sapi bersayap terbang di udara. Suatu hal yang aneh! Anda pernah mendengar tentang babi terbang sebelumnya, tapi sapi? Ini memang suatu hal yang baru dan aneh! Sapi dengan sayap! Sungguh konyol membayangkannya.', 'Anda menginginkan sesuatu yang dapat membantu Anda terbang bersama sapi, jadi Anda mengenakan sepatu terbang (ぶつ). Sepatu bot terbang Anda memang cukup aneh, tetapi itulah satu-satunya cara agar Anda bisa mengimbanginya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
