INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('eb8d68d2-054f-4a19-ad6b-ebc075408b01', 'kanji', '的', '的', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Seorang pria kulit putih melompat ke dalam kolam dengan target dicat di bagian bawah. Dia mengincar sasarannya.', 'Pria berkulit putih ini adalah seorang teknisi hebat (てき) sehingga dia memiliki peningkatan elektronik yang memastikan dia mencapai target. Menjadi seorang teknisi memiliki kelebihan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
