INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('2871ccf9-b0d7-42cf-9d17-ea46b49ee525', 'kanji', '使', '使', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Seorang pemimpin yang baik akan mampu memanfaatkan sejarah yang ada di lingkungannya. Anda adalah pemimpin yang baik. Anda telah mempelajari tanah dan kotoran bumi sepanjang hidup Anda. Anda tahu sejarah lapangan dan Anda tahu bagaimana menggunakannya untuk memimpin orang-orang Anda.', 'Anda menggunakan tanah untuk beternak domba (し). Ketika Anda berada di sana sambil mengendus-endus, Anda menyadari bahwa orang-orang Anda akan berkembang paling baik jika Anda menggunakan tanah ini untuk penggembalaan dan beternak domba.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
