INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('8c042927-b9b3-479c-b23c-9e7f3e863f74', 'kanji', '画', '画', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ada gambar daun di sawah dari dekat di dalam kotak. Tunggu, ini bukan sebuah kotak, semua ini hanya sebuah gambar.', 'Gambar tersebut sepertinya memiliki sesuatu yang lain di sawah, di balik daun. Anda menyadari bahwa gambar tersebut sebenarnya adalah gargoyle (が) dan seekor ayam jantan (かく). Anda melihat ayam jantan duduk di atas gargoyle, berkokok ke langit.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
