INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('8cda590f-6f3c-48a3-b737-5d0cdcf10442', 'kanji', '味', '味', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Apa pancaran mulutmu? Itu rasanya. Itu yang membuat Anda terkagum-kagum, yang menjelaskan mengapa sangat sakit saat Anda makan sesuatu yang enak.', 'Dan rasa apa yang lebih enak daripada sepotong besar daging (み)? Anda menyukai daging dan rasanya sama seperti Anda menyukai rasa jusnya. Begitu banyak hal baik untuk dimasukkan ke dalam mulut Anda!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
