INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('6eb5c8a5-d257-4288-9252-00ded7d1ccad', 'kanji', '歩', '歩', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda berhenti di sebuah perosotan kecil. Apa yang kamu lakukan sebelum berhenti di sini? Anda sedang berjalan.', 'Jadi, Anda sedang berjalan-jalan, mengurus urusan Anda sendiri, ketika tiba-tiba sesuatu terjadi dan menghantam wajah Anda. Anda menginjak kepala cangkul (ほ) dan hal itu menyebabkan cangkul itu terayun dari tanah dan mengenai Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
