INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('89647fd1-d5c6-4ab4-88eb-3d00b816567c', 'kanji', '注', '注', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Seorang ahli tsunami mempunyai kekuatan untuk menuangkan air kemanapun dia mau. Ahli tsunami adalah ahli dalam menggunakan kekuatan air yang paling kuat di alam semesta, jadi masuk akal jika mereka mempunyai kemampuan untuk menuangkan air sesuka hati, ke mana pun mereka mau. Sebaiknya jangan centang masternya, kecuali Anda ingin tsunami menimpa kepala Anda.', 'Jika Chewbacca (ちゅう) mencoba menyerang Anda, Anda akan dapat mempertahankan diri dengan mudah. Cukup tuangkan tsunami padanya dan Chewbacca akan menyerah dalam sekejap. Chewbacca tidak suka air disiramkan ke tubuhnya, apalagi air yang berasal dari tsunami tidak semuanya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
