INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('289af712-8b72-4233-a415-310633928bef', 'kanji', '京', '京', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ada penutup yang menutupi seluruh mulut yang terlalu kecil untuk memberi makan, membentuk ibu kota. Semua mulut kecil bersatu dan menciptakan tempat di mana setiap orang dapat saling mendukung.', 'Untuk mengingat bacaan きょう kita menggunakan kota di Jepang, Kyoto, yang dieja きょうと. Dulunya merupakan ibu kota Jepang! Itu sangat penuh dengan mulut yang menyatu sehingga menjadi ibu kota untuk waktu yang sangat lama.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
