INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('bee201af-4449-4bb7-aeaf-20800d42f440', 'kanji', '英', '英', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ada banyak bunga di pusat Inggris. Pada awalnya mungkin tampak hujan dan kelabu, tetapi jika Anda berjalan tepat ke pusat kota, Anda akan melihat semua bunga yang tumbuh di tengah negara tersebut.
