INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d04aadb6-c5bd-4b26-adcf-02aa13c3088e', 'ぶじに、女の赤ちゃんがうまれました。', 'Bayi perempuan itu lahir tanpa komplikasi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d04aadb6-c5bd-4b26-adcf-02aa13c3088e', 'このかわいい女の子の赤ちゃんの名まえはエマちゃんです。', 'Nama bayi perempuan lucu ini adalah Emma.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d04aadb6-c5bd-4b26-adcf-02aa13c3088e', 'あなたの赤ちゃんの頃の写真が見てみたいわ。', 'Aku ingin melihat fotomu saat kamu masih bayi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('92673caf-92fc-4a73-ac71-46df0fdb7f70', 'vocabulary', '空気', '空気', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Energi langit... pernah dikenal sebagai benda mistis yang menghalangi kita terbang ke luar angkasa. Sekarang kita tahu ini adalah udara. Namun bisa juga berarti atmosfer, karena itulah sebutan kumpulan udara antara bumi dan luar angkasa. ここの空気はいいね！', 'Energi langit... pernah dikenal sebagai benda mistis yang menghalangi kita terbang ke luar angkasa. Sekarang kita tahu ini adalah udara. Namun bisa juga berarti atmosfer, karena itulah sebutan kumpulan udara antara bumi dan luar angkasa. ここの空気はいいね！') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
