INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1068a532-579e-491d-82d8-d2dce7b73142', '下の図を見てください。', 'Silakan lihat diagram di bawah ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1068a532-579e-491d-82d8-d2dce7b73142', 'クリックすると、かく大図がひょうじされます。', 'Jika diklik maka akan muncul tampilan yang diperbesar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1068a532-579e-491d-82d8-d2dce7b73142', 'あなたのお兄さんは、自分と彼女の関係を簡単な図に表しました。', 'Kakakmu menggambar diagram sederhana tentang hubungan antara dia dan pacarnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('67ecb7a3-0a3a-4abb-9b91-84be40f62164', 'vocabulary', '売る', '売る', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menjual, jadi versi kata kerjanya adalah menjual sesuatu.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menjual, jadi versi kata kerjanya adalah menjual sesuatu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
