INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('67ecb7a3-0a3a-4abb-9b91-84be40f62164', 'ここに、日本ごのじしょは売っていますか。', 'Apakah kamus bahasa Jepang dijual di sini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('67ecb7a3-0a3a-4abb-9b91-84be40f62164', 'この村では、人々は大麦を売って生けいを立てています。', 'Di desa ini, masyarakat mencari nafkah dengan berjualan jelai.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('67ecb7a3-0a3a-4abb-9b91-84be40f62164', '請求書の支払いをするために車を売る必要があるが、そうすれば今度は仕事にいけなくなってしまう。', 'Saya perlu menjual mobil saya untuk membayar tagihan, tetapi jika saya menjualnya, saya tidak dapat mulai bekerja.') ON CONFLICT DO NOTHING;
