INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0fcabe62-7fc9-41ce-9b35-67d87bd78ec3', 'だんだん売り上げがへってきた。', 'Penjualan secara bertahap menurun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0fcabe62-7fc9-41ce-9b35-67d87bd78ec3', 'アメリカ人人気はいゆうが主えんしたハリウッドえいがのDVDは、日本だけで売り上げが八百万まいになった。', 'DVD film Hollywood yang dibintangi aktor populer Amerika sebagai karakter utamanya telah terjual delapan juta kopi di Jepang saja.') ON CONFLICT DO NOTHING;
