INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('afb51a78-2429-462c-a4ba-7d267b688216', '今夜、いっしょにのみに行きませんか。', 'Maukah kamu pergi minum bersamaku malam ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('afb51a78-2429-462c-a4ba-7d267b688216', '明日しけんがあるから、今夜はてつ夜でがんばります。', 'Besok ujiannya akan datang, jadi aku akan membakar minyak tengah malam malam ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('afb51a78-2429-462c-a4ba-7d267b688216', '今夜は晩ご飯に手羽先が食べたい気分だ。', 'Saya ingin makan sayap ayam untuk makan malam malam ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('be92ddf1-fc03-403a-844e-43fe3cb2323d', 'vocabulary', '店', '店', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
