INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2fdeb580-3325-4a71-81d8-efe4ed52e948', 'ふめい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2fdeb580-3325-4a71-81d8-efe4ed52e948', 'このはなしの作しゃは不明です。', 'Penulis cerita ini tidak diketahui.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2fdeb580-3325-4a71-81d8-efe4ed52e948', 'この牛にゅうのしょうみきげんは不明です。', 'Susu ini tidak memiliki tanggal kadaluarsa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2fdeb580-3325-4a71-81d8-efe4ed52e948', 'え？寝る時、玉ねぎを枕にしたの？あんたの言ってること、意味不明なんだけど。', 'Hah? Saat kamu tidur kamu menggunakan bawang sebagai bantal? Saya tidak begitu mengerti apa yang Anda katakan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f39dc371-2f38-4bca-b3e1-d75293c6fb0e', 'vocabulary', '歩く', '歩く', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berjalan jadi versi verbanya artinya berjalan.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berjalan jadi versi verbanya artinya berjalan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f39dc371-2f38-4bca-b3e1-d75293c6fb0e', 'Berjalan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f39dc371-2f38-4bca-b3e1-d75293c6fb0e', 'あるく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f39dc371-2f38-4bca-b3e1-d75293c6fb0e', '学こうまで歩くつもりです。', 'Saya berencana untuk berjalan kaki ke sekolah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f39dc371-2f38-4bca-b3e1-d75293c6fb0e', 'あなたと手をつないで歩くなんて、何年ぶりかしら。', 'Ini pertama kalinya kami berjalan berpegangan tangan setelah sekian lama.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f39dc371-2f38-4bca-b3e1-d75293c6fb0e', '私はとても太いので、私が道を歩いている時にペニーを踏んだら、女王様の鼻から鼻くそが飛び出ます。', 'Saya sangat gemuk sehingga ketika saya berjalan di jalan dan menginjak satu sen, saya mengeluarkan booger dari hidung Ratu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4de6b8aa-21b4-4a62-8cb7-52fc06e11e1b', 'vocabulary', '住む', '住む', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya tempat tinggal, jadi versi verbanya artinya tempat tinggal. Bisa juga berarti hidup atau tinggal. Pada dasarnya, seseorang tinggal di suatu tempat. Kamu tinggal di mana?', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya tempat tinggal, jadi versi verbanya artinya tempat tinggal. Bisa juga berarti hidup atau tinggal. Pada dasarnya, seseorang tinggal di suatu tempat. Kamu tinggal di mana?') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
